package dao;import model.*;import java.sql.*;import java.time.*;import java.math.*;import java.util.*;
public class OrderDAO5 extends DAO5{public OrderDAO5(Connection c){super(c);}public Order5 createOrder(Customer5 c,Ticket5[] ts,MembershipCard5 card)throws Exception{if(ts.length==0)throw new IllegalArgumentException("Đơn không có vé");Order5 o=new Order5();o.setMaGiaoDich("GD"+UUID.randomUUID().toString().replace("-", "").substring(0,20));o.setHinhThucMua("TRUC_TUYEN");o.setThoiGianTao(LocalDateTime.now());o.setTrangThai("CHO_THANH_TOAN");o.setThanhVien(c);o.setThe(card);o.setVe(ts);o.setThanhToan(new Payment5[0]);o.setTongTien(Arrays.stream(ts).map(Ticket5::getGia).reduce(BigDecimal.ZERO,BigDecimal::add));o.setId(insert("INSERT INTO tblOrder5(MaGiaoDich,HinhThucMua,ThoiGianTao,TrangThai,tblCustomer5id,tblMembershipCard5id) VALUES(?,?,?,?,?,?)",o.getMaGiaoDich(),o.getHinhThucMua(),o.getThoiGianTao(),o.getTrangThai(),c.getId(),card==null?null:card.getId()));return o;}
public Order5 confirmPayment(Order5 o,Payment5 p)throws Exception{if(!"SUCCESS".equals(p.getTrangThai()))throw new IllegalArgumentException("Thanh toán chưa thành công");update("UPDATE tblOrder5 SET TrangThai='DA_THANH_TOAN' WHERE id=?",o.getId());o.setTrangThai("DA_THANH_TOAN");o.setThanhToan(new Payment5[]{p});return o;}
public Order5 createReceipt(Order5 o)throws Exception{if(!"DA_THANH_TOAN".equals(o.getTrangThai()))throw new IllegalStateException("Đơn chưa thanh toán");o.setMaHoaDon("HD"+o.getMaGiaoDich().substring(2));o.setNgayLap(LocalDateTime.now());update("UPDATE tblOrder5 SET MaHoaDon=?,NgayLap=? WHERE id=?",o.getMaHoaDon(),o.getNgayLap(),o.getId());return o;}
public Order5 get(int id,int customerId)throws Exception{try(PreparedStatement p=stmt("SELECT * FROM tblOrder5 WHERE id=? AND tblCustomer5id=?",id,customerId);ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Không tìm thấy đơn của bạn");Order5 o=map(r,Order5.class);o.setThanhVien(new MemberDAO5(con).customer(customerId));int card=r.getInt("tblMembershipCard5id");if(card!=0){List<MembershipCard5>a=query(MembershipCard5.class,"SELECT * FROM tblMembershipCard5 WHERE id=?",card);o.setThe(a.get(0));}List<Ticket5> ts=new ArrayList<>();try(PreparedStatement q=stmt("SELECT * FROM tblTicket5 WHERE tblOrder5id=?",id);ResultSet v=q.executeQuery()){while(v.next()){Ticket5 t=map(v,Ticket5.class);t.setSuatChieu(new ScreeningDAO5(con).get(v.getInt("tblScreening5id")));t.setGhe(query(Seat5.class,"SELECT * FROM tblSeat5 WHERE id=?",v.getInt("tblSeat5id")).get(0));ts.add(t);}}o.setVe(ts.toArray(new Ticket5[0]));o.setThanhToan(query(Payment5.class,"SELECT * FROM tblPayment5 WHERE tblOrder5id=? ORDER BY id",id).toArray(new Payment5[0]));o.setTongTien(ts.stream().map(Ticket5::getGia).reduce(BigDecimal.ZERO,BigDecimal::add));return o;}}
public Order5[] history(int customerId)throws Exception{List<Order5>a=query(Order5.class,"SELECT * FROM tblOrder5 WHERE tblCustomer5id=? AND TrangThai='DA_THANH_TOAN' ORDER BY id DESC",customerId);for(int i=0;i<a.size();i++)a.set(i,get(a.get(i).getId(),customerId));return a.toArray(new Order5[0]);}}
